import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SLOP_REASONS, SLOP_REASON_LABELS } from "./slop.js";

// The runtime list must match the API's OpenAPI document (regenerated by `pnpm sdk`), in order.
const openapi = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as {
  components: { schemas: Record<string, { properties: Record<string, { items?: { enum?: string[] } }> }> };
};

describe("slop reasons", () => {
  it("match the OpenAPI enum, each with a label", () => {
    expect([...SLOP_REASONS]).toEqual(openapi.components.schemas.SlopSummary!.properties.topReasons!.items!.enum);
    expect(Object.keys(SLOP_REASON_LABELS).sort()).toEqual([...SLOP_REASONS].sort());
  });
});
